// Classic stack use: balanced brackets
boolean balanced(String s) {
    Deque<Character> open = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (c == '(') open.push(c);
        else if (c == ')' && (open.isEmpty() || open.pop() != '(')) return false;
    }
    return open.isEmpty();
}

// WRONG: add() goes to the END, pop() takes from the FRONT -> FIFO, not LIFO
Deque<String> stack = new ArrayDeque<>();
stack.add("first");
stack.add("second");
stack.pop();                // "first" — not what a stack should return

// RIGHT: push/pop/peek for a stack
stack.push("first");
stack.push("second");
stack.pop();                // "second"

