List<Integer> ids = new ArrayList<>(List.of(42, 7, 19, 3));
Collections.binarySearch(ids, 19);    // undefined: may return a negative number

// RIGHT: sort first (or use a HashSet if you only need "contains")
Collections.sort(ids);                // [3, 7, 19, 42]
