// RIGHT
people.sort(Comparator.comparingInt(Person::score));
people.sort((a, b) -> Integer.compare(a.score(), b.score()));

// Total of a category and all its subcategories
BigDecimal total(Category c) {
    BigDecimal sum = c.ownTotal();                 // the work at this level
    for (Category child : c.children()) {
        sum = sum.add(total(child));               // a smaller version of the problem
    }
    return sum;                                    // a leaf has no children: base case
}

int factorial(int n) {
    if (n <= 1) return 1;                          // base case
    return n * factorial(n - 1);                   // moves toward the base case
}

// WRONG: one stack frame per node -> StackOverflowError on long lists
int length(Node node) {
    return node == null ? 0 : 1 + length(node.next);
}

// RIGHT: iterative, constant stack
int length(Node node) {
    int count = 0;
    for (Node n = node; n != null; n = n.next) count++;
    return count;
}
